"""Scaffold file templates written by `tuvl init`.

Pure content constants (sample YAML, code agents, AGENTS.md, skills) live here
so init.py stays focused on the init flow rather than the file bodies it writes.
"""


# Sample file content — recruitment use case, one of each YAML kind + a node.

_SAMPLE_CANDIDATE_MODEL = """\
# ╔══════════════════════════════════════════════════════════════════════════╗
# ║  SAMPLE FILE — generated by `tuvl init --sample`                        ║
# ║                                                                          ║
# ║  enabled: false  →  tuvl loads this file but does NOT create the table   ║
# ║  or expose any CRUD endpoints until you flip this to true.               ║
# ║                                                                          ║
# ║  spec.api.crud  →  the /models/* CRUD routes this model exposes; none    ║
# ║  by default. List only what a client needs, e.g. [list, read]. Each      ║
# ║  route requires the model's read / write / delete scope (spec.access).   ║
# ║                                                                          ║
# ║  For AI / LLM agents reading this file:                                  ║
# ║    This is a ModelDefinition — it declares a database table schema.      ║
# ║    Study the field types, required flags, and descriptions to understand ║
# ║    the data shape.  When generating new models, follow this structure.   ║
# ║    Remove or rename this file once you have created your own model.      ║
# ╚══════════════════════════════════════════════════════════════════════════╝
kind: ModelDefinition
version: v1
enabled: false
metadata:
  name: Candidate
  schema_version: v1
  description: >
    Job candidate submitted for screening.
    Demonstrates every supported field type.
spec:
  tablename: candidates
  api:
    crud: []           # CRUD routes to expose: list, read, create, update, delete
  fields:
    # ── Identity ────────────────────────────────────────────────────────────
    - name: id
      type: uuid           # UUID — auto-generated primary key (server default)
      primary_key: true
      input: false         # server-generated — omit from Create/Update schemas

    # ── Short strings ────────────────────────────────────────────────────────
    - name: name
      type: string         # VARCHAR (≤ 255 chars) — general short text
      required: true
      description: Full name of the candidate

    - name: email
      type: string
      required: true
      unique: true
      description: Contact email — enforces uniqueness at DB level

    - name: role
      type: string
      description: Job role the candidate applied for

    - name: status
      type: enum
      enum_values: [new, screened, interviewed, offered, rejected]
      default: new         # new is the initial state on creation
      required: true
      description: Lifecycle status of the candidate
      index: true          # index speeds up status-based filtering
      # Use type: enum (not type: string) for any finite, stable set of values.
      # The DB enforces the constraint; Pydantic rejects invalid values at the API layer.

    - name: source
      type: varchar        # VARCHAR — identical to string, explicit alias
      description: Referral channel — linkedin | referral | direct | agency

    # ── Long / rich text ─────────────────────────────────────────────────────
    - name: cover_letter
      type: text           # TEXT — unbounded length, ideal for long prose
      description: Free-form cover letter text submitted by the candidate

    # ── Numeric ──────────────────────────────────────────────────────────────
    - name: experience_years
      type: integer        # INTEGER (32-bit) — whole-number years
      default: 0
      description: Total professional experience in whole years

    - name: total_applications
      type: bigint         # BIGINT (64-bit) — counts that can exceed 2 billion
      default: 0
      description: Lifetime application count across all roles

    - name: priority_rank
      type: smallint       # SMALLINT (16-bit) — small enumerations, saves space
      default: 5
      description: Review priority 1 (highest) – 10 (lowest)

    - name: score
      type: numeric        # NUMERIC / DECIMAL — exact fixed-point, ideal for scores
      description: Composite screening score (0 – 100)

    - name: ai_confidence
      type: float          # FLOAT (double precision) — approx. floating-point
      description: LLM confidence in the recommendation (0.0 – 1.0)

    # ── Boolean ──────────────────────────────────────────────────────────────
    - name: remote_ok
      type: boolean        # BOOLEAN — true / false
      default: false
      description: Whether the candidate is open to remote work

    - name: verified
      type: boolean
      default: false
      description: True once identity and references have been verified

    # ── Date / time ──────────────────────────────────────────────────────────
    # A date/timestamp with NO default is nullable business data: it persists as
    # NULL when the caller omits it (it is never silently auto-set to today/now).
    # To auto-populate a value, opt in explicitly with `default: today` (date) or
    # `default: now` (timestamp/timestamptz) — or name the column created_at /
    # updated_at to pick up the audit-column convention automatically.
    - name: available_from
      type: date           # DATE — calendar date without time component
      description: Earliest start date the candidate can join (NULL until supplied)

    - name: submitted_at
      type: timestamp      # TIMESTAMP — date + time, no timezone
      default: now         # auto-set to the current time on create
      description: When the application was submitted (UTC assumed)

    - name: last_contacted_at
      type: timestamptz    # TIMESTAMPTZ — date + time WITH timezone (recommended)
      description: Last outreach timestamp (NULL until the first contact is made)

    # ── Structured / binary ──────────────────────────────────────────────────
    - name: evaluation
      type: jsonb          # JSONB — binary JSON, indexable, ideal for LLM output
      description: Structured evaluation returned by the agent step

    - name: skills
      type: jsonb
      description: JSON array of skill tags e.g. ["python", "ml", "fastapi"]

    - name: resume_file
      type: bytea          # BYTEA — raw binary blob, e.g. PDF resume bytes
      description: Raw binary content of the uploaded resume (PDF / DOCX)
      # secure: true       # uncomment to redact this field in all logs and API responses

  # ── Optional: explicit datasource binding ────────────────────────────────
  # By default tuvl binds every model to the primary DataSource (the one
  # carrying metadata.primary: true, or the first registered Postgres).
  # Set spec.datasource to route this model to a different DataSource YAML.
  #
  # datasource: analytics    # references metadata.name of another DataSource YAML

  # ── Optional: CRUD access scope overrides ────────────────────────────────
  # By default tuvl gates CRUD routes on {modelname.lower()}:read/write/delete scopes.
  # Use spec.access to override these scope names for this model.
  # Tokens carrying iam:admin bypass all scope checks regardless.
  #
  # access:
  #   read_scope:   hr_data:read    # default: candidate:read
  #   write_scope:  hr_data:write   # default: candidate:write
  #   delete_scope: hr_data:delete  # default: candidate:delete

  # ── Optional: relations (eager-loadable joins) ────────────────────────────
  # Declared relations can be eager-loaded in ModelOp steps via the include: field.
  # Two cardinalities are supported: many_to_one and one_to_many.
  #
  # relations:
  #   - name: applications         # the key injected into the record dict on eager-load
  #     model: Application         # ModelDefinition.metadata.name of the related model
  #     foreign_key: candidate_id  # column on Application pointing back to Candidate
  #     type: one_to_many          # many_to_one | one_to_many
  #
  #   - name: company              # many_to_one: each Candidate belongs to one Company
  #     model: Company
  #     foreign_key: id            # PK column on Company
  #     type: many_to_one
"""

_SAMPLE_DATASOURCE = """\
# ╔══════════════════════════════════════════════════════════════════════════╗
# ║  SAMPLE FILE — generated by `tuvl init --sample`                        ║
# ║                                                                          ║
# ║  enabled: false  →  tuvl skips this datasource at startup.              ║
# ║  Set enabled: true (or remove the line) once you have filled in your     ║
# ║  real connection details in .env.                                        ║
# ║                                                                          ║
# ║  For AI / LLM agents reading this file:                                  ║
# ║    This is a DataSource definition — it tells tuvl how to connect to a  ║
# ║    PostgreSQL database.  All credentials must come from env vars (${}).  ║
# ║    metadata.primary: true makes this the implicit datasource for every   ║
# ║    model that does not specify spec.datasource explicitly.               ║
# ║    Copy this file, rename it, and adjust the connection block to add     ║
# ║    additional database connections.                                      ║
# ╚══════════════════════════════════════════════════════════════════════════╝
# ── DataSource — PostgreSQL ───────────────────────────────────────────────────
#
# A DataSource configures a database backend that tuvl can query via ModelOp
# steps and the auto-generated CRUD endpoints.
#
# kind:     Always "DataSource"
# version:  Schema version — use "v1"
# metadata.name:
#   The identifier used to reference this datasource in model YAMLs.
#   Set spec.datasource: <name> on a ModelDefinition to bind a model to it.
#   If omitted on a model, the primary DataSource is used.
#
# spec.type:    Database dialect.  Currently supported: postgresql
# spec.driver:  Async driver for SQLAlchemy.  Use "asyncpg" for PostgreSQL.
#
# spec.connection:
#   host, port, database, username, password
#   Any value starting with $ is resolved from the environment at startup,
#   e.g. password: ${POSTGRES_PASSWORD} reads the env var POSTGRES_PASSWORD.
#
# spec.pooling:
#   min_size  — minimum idle connections kept alive
#   max_size  — maximum concurrent connections
#   Omit this block to use the driver defaults.
#
# metadata.primary:
#   Set to true on exactly one DataSource to designate it as the primary
#   Postgres backend (used for the tuvl_system_registry lock and IAM tables).
#   If no datasource carries this flag, tuvl falls back to the first
#   registered PostgreSQL datasource.
#
kind: DataSource
version: v1
enabled: false
metadata:
  name: default
  primary: true
  description: >
    Primary PostgreSQL datasource.
    Credentials are loaded from environment variables defined in .env.
spec:
  type: postgresql
  driver: asyncpg
  connection:
    host: ${POSTGRES_HOST}
    port: ${POSTGRES_PORT}
    database: ${POSTGRES_DB}
    username: ${POSTGRES_USER}
    password: ${POSTGRES_PASSWORD}
  pooling:
    min_size: 2
    max_size: 10
"""

_SAMPLE_LLM = """\
# ╔══════════════════════════════════════════════════════════════════════════╗
# ║  SAMPLE FILE — generated by `tuvl init --sample`                        ║
# ║                                                                          ║
# ║  enabled: false  →  tuvl ignores this AgentModel at startup.            ║
# ║  Set enabled: true once you have set the correct env vars in .env and   ║
# ║  chosen the provider/model string below.                                 ║
# ║                                                                          ║
# ║  For AI / LLM agents reading this file:                                  ║
# ║    This is an AgentModel definition — it configures which language model ║
# ║    tuvl uses for agent steps that specify  model: default.               ║
# ║    Change the "model:" line to switch providers (openai/gpt-4o,          ║
# ║    anthropic/claude-sonnet-4-5, groq/llama3-8b-8192,…).       ║
# ║    api_key must always reference an env var — never hard-code secrets.   ║
# ╚══════════════════════════════════════════════════════════════════════════╝
# ── AgentModel — LLM provider configuration ───────────────────────────────────
#
# An AgentModel defines how tuvl calls a language model.
# Each agent step references one AgentModel by its metadata.name.
# The file is named llms/<name>.yaml; "default" is the conventional fallback.
#
# kind:     Always "AgentModel"
# metadata.name:
#   The identifier used in workflow YAML:  agent.model: <name>
#   If the value contains a "/" it is treated as a raw model id
#   (e.g. "openai/gpt-4o") and no llms/ file is looked up.
#
# model:
#   Model id.  Format: <provider>/<model-id>
#   Examples:
#     openai/gpt-4o
#     anthropic/claude-sonnet-4-5
#     ollama/llama3
#     groq/llama3-8b-8192
#     gemini/gemini-1.5-pro
#
# api_base:
#   Required for self-hosted / local models (Ollama, vLLM, any OpenAI-compatible gateway).
#   Can reference an env var: api_base: ${OLLAMA_BASE_URL}
#
# api_key:
#   Required for hosted providers.  Always reference an env var — never
#   paste a real key here.  Pattern: api_key: ${OPENAI_API_KEY}
#
# temperature:  Sampling temperature (0.0 = deterministic, 1.0 = creative)
# max_tokens:   Hard cap on response length.  Omit to use provider default.
# timeout:      Request timeout in seconds.  Omit to use provider default.
#
kind: AgentModel
version: v1
enabled: false
metadata:
  name: default
  description: >
    Default LLM used by agent steps that specify  model: default.
    Swap the model string and credentials to switch providers without
    changing any workflow YAML.
spec:
  model: ollama/llama3
  api_base: ${OLLAMA_BASE_URL}
  # api_key: ${OPENAI_API_KEY}     # uncomment for OpenAI / Anthropic / Groq
  temperature: 0.3                 # lower = more deterministic; raise for creative tasks
  max_tokens: 1024
  timeout: 60
"""

