_SAMPLE_TRIAGE_WORKFLOW = """\
# ╔══════════════════════════════════════════════════════════════════════════╗
# ║  SAMPLE FILE — generated by `tuvl init --sample`                        ║
# ║                                                                          ║
# ║  Every node is an agent with a typed contract (inputs → outputs) and    ║
# ║  named routes. This one uses four engines:                              ║
# ║    llm    classify   — structured output from the declared outputs      ║
# ║    code   prioritise — agents/prioritise_ticket.py (@agent)              ║
# ║    human  review     — a lead approves urgent tickets (202 + approval)  ║
# ║    tool   store      — a db create that commits with its checkpoint     ║
# ║  Set llms/default.yaml enabled: true and a provider key in .env to run. ║
# ╚══════════════════════════════════════════════════════════════════════════╝
kind: Workflow
version: tuvl/v2
metadata:
  name: triage_ticket
  description: Classify a support ticket, route urgent ones to a lead, and store it.
spec:
  models: [Ticket]
  trigger:
    http: { path: /api/tickets/triage, method: POST }
    input:
      subject: str
      body: str
      customer_email: str

  agents:
    - id: classify
      description: Classify the ticket's category and urgency
      engine: llm
      inputs: { subject: str, body: str }
      outputs:
        category: "enum[billing, technical, account]"
        urgency: "enum[low, high]"
        summary: str
      budget:
        timeout: 30s
        max_tokens: 500
        retry: { attempts: 2, errors: [parse_error, timeout] }
      llm:
        model: default
        system: You triage customer support tickets. Summarise in one sentence.
        prompt: Classify this ticket.
      routes:
        default: prioritise
        parse_error: END.failed
        timeout: END.failed
        budget_exceeded: END.failed
        error: END.failed

    - id: prioritise
      description: Decide whether a lead must review the ticket first
      engine: code
      effect: read
      code: { run: prioritise_ticket }
      inputs:
        category: "enum[billing, technical, account]"
        urgency: "enum[low, high]"
      routes:
        urgent: review
        normal: store
        error: END.failed

    - id: review
      description: A support lead approves an urgent ticket
      engine: human
      inputs: { subject: str, summary: str, category: "enum[billing, technical, account]" }
      outputs: { approved: bool, note: "str?" }
      human:
        title: "Urgent ticket: {{ subject }}"
        instruction: Approve to queue this ticket for the on-call team.
        show: [subject, summary, category]
        required_group: support_leads
        expires: 4h
        route_on: approved
      routes:
        "true": store
        "false": END.dismissed
        expired: store
        error: END.failed

    - id: store
      description: Store the classified ticket
      engine: tool
      inputs:
        subject: str
        body: str
        customer_email: str
        category: "enum[billing, technical, account]"
        urgency: "enum[low, high]"
        summary: str
      outputs: { ticket: Ticket }
      tool:
        use: db
        model: Ticket
        op: create
        values:
          subject: "{{ subject }}"
          body: "{{ body }}"
          customer_email: "{{ customer_email }}"
          category: "{{ category }}"
          urgency: "{{ urgency }}"
          summary: "{{ summary }}"
      routes:
        default: END
        conflict: END.failed
        error: END.failed

  outputs:
    default:
      status: 201
      body: { id: "{{ ticket.id }}", category: "{{ ticket.category }}", urgency: "{{ ticket.urgency }}" }
    dismissed:
      status: 200
      body: { status: dismissed }
    failed:
      status: 422
      body: { error: the ticket could not be triaged }
"""

_SAMPLE_PRIORITISE_AGENT = '''\
"""Sample code agent — generated by `tuvl init --sample`.

A code agent receives exactly its declared inputs (here: category and
urgency) and returns its outputs, an (outputs, signal) pair, or a bare
signal. This one only routes: "urgent" goes to a lead, "normal" is stored.
"""

from tuvl import Ctx, agent


@agent("prioritise_ticket")
async def prioritise_ticket(inp, ctx: Ctx) -> str:
    if inp.urgency == "high" or inp.category == "billing":
        return "urgent"
    return "normal"
'''

