# The deterministic gate, as CI. Pull requests run the checks that fail on errors (a scaffold or a
# half-built stack still has pending steps and unfinished tasks); pushes to the main branches also
# run them strictly.
_GATE = (
    "tuvl lint spec",
    "tuvl lint project",
    "tuvl generate code --check",
    "tuvl verify lock",
    "tuvl run tests",
    "tuvl verify spec",
    "tuvl review code",
)
_STRICT = (
    "tuvl lint spec --strict",
    "tuvl lint project --strict",
    "tuvl generate code --check",
    "tuvl verify lock",
    "tuvl run tests --strict",
    "tuvl verify spec --strict",
    "tuvl list tasks --strict",
    "tuvl review code --strict",
)


def github_workflow() -> str:
    gate = "".join(f"      - run: uv run {c}\n" for c in _GATE)
    strict = "".join(f"      - run: uv run {c}\n" for c in _STRICT)
    return (
        "# The deterministic gate: no model, no tokens. Generated by `tuvl init --ci github`.\n"
        "name: tuvl\n"
        "on:\n"
        "  pull_request:\n"
        "    branches: [develop, main]\n"
        "  push:\n"
        "    branches: [develop, main]\n"
        "jobs:\n"
        "  gate:\n"
        "    name: Gate (errors fail)\n"
        "    if: github.event_name == 'pull_request'\n"
        "    runs-on: ubuntu-latest\n"
        "    steps:\n"
        "      - uses: actions/checkout@v4\n"
        "      - uses: astral-sh/setup-uv@v5\n"
        "      - run: uv sync\n"
        f"{gate}"
        "  strict:\n"
        "    name: Gate (strict)\n"
        "    if: github.event_name == 'push'\n"
        "    runs-on: ubuntu-latest\n"
        "    steps:\n"
        "      - uses: actions/checkout@v4\n"
        "      - uses: astral-sh/setup-uv@v5\n"
        "      - run: uv sync\n"
        f"{strict}"
    )


def gitlab_pipeline() -> str:
    gate = "".join(f"    - uv run {c}\n" for c in _GATE)
    strict = "".join(f"    - uv run {c}\n" for c in _STRICT)
    return (
        "# The deterministic gate: no model, no tokens. Generated by `tuvl init --ci gitlab`.\n"
        "default:\n"
        "  image: ghcr.io/astral-sh/uv:python3.13-bookworm\n"
        "gate:\n"
        "  rules:\n"
        '    - if: $CI_PIPELINE_SOURCE == "merge_request_event"\n'
        "  script:\n"
        "    - uv sync\n"
        f"{gate}"
        "strict:\n"
        "  rules:\n"
        '    - if: $CI_COMMIT_BRANCH == "develop" || $CI_COMMIT_BRANCH == "main"\n'
        "  script:\n"
        "    - uv sync\n"
        f"{strict}"
    )
